// LeoPhoneAgent：只有本表单刚提交的保存，才从编辑层扣除已保存的字段。运行中的智能体会因
// 状态/心跳实时事件被频繁重新获取，旧逻辑在任何一次刷新时清空整个编辑层，用户尚未保存的
// 修改会被"自动刷新"掉。与保存无关的刷新现在保留编辑层。
const persisted = backgroundSaveOverlayRef.current ?? foregroundSaveOverlayRef.current;
backgroundSaveOverlayRef.current = null;
foregroundSaveOverlayRef.current = null;
if (persisted) setOverlay((prev) => subtractPersistedOverlay(prev, persisted));

